import{_ as t,o as a,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const f=JSON.parse('{"title":"Default Approval and Completion Checklist","description":"The final definition of the Hearth default approval checklist, default completion checklist, and task overrides.","frontmatter":{"title":"Default Approval and Completion Checklist","description":"The final definition of the Hearth default approval checklist, default completion checklist, and task overrides.","outline":[2,3]},"headers":[],"relativePath":"en/reference/checklists.md","filePath":"en/reference/checklists.md","lastUpdated":1793706118000}'),o={name:"en/reference/checklists.md"};function r(n,e,s,c,d,h){return a(),i("div",null,[...e[0]||(e[0]=[l('<p class="eyebrow">CHECKLISTS</p><h1 id="default-approval-and-completion-checklists" tabindex="-1">Default Approval and Completion Checklists <a class="header-anchor" href="#default-approval-and-completion-checklists" aria-label="Permalink to &quot;Default Approval and Completion Checklists&quot;">​</a></h1><p class="lead">Put these checklists into Task templates, approval interfaces, and acceptance workflows, rather than leaving them in documentation.</p><h2 id="default-approval-checklist" tabindex="-1">Default Approval Checklist <a class="header-anchor" href="#default-approval-checklist" aria-label="Permalink to &quot;Default Approval Checklist&quot;">​</a></h2><p>Before any high-risk action, confirm each item:</p><ul><li>[ ] The action type is correct;</li><li>[ ] The target recipient/file/repository/calendar/resource is correct;</li><li>[ ] The account used is correct;</li><li>[ ] The content and attachments are correct;</li><li>[ ] The scope does not exceed the Mandate;</li><li>[ ] Whether it is reversible has been stated;</li><li>[ ] The failure and reconciliation approach has been stated;</li><li>[ ] The approval has a nonce and expiry time;</li><li>[ ] A Receipt and rollback/compensation are prepared;</li><li>[ ] No security controls are bypassed.</li></ul><h2 id="default-completion-checklist" tabindex="-1">Default Completion Checklist <a class="header-anchor" href="#default-completion-checklist" aria-label="Permalink to &quot;Default Completion Checklist&quot;">​</a></h2><p>Before marking a Task complete, confirm each item:</p><ul><li>[ ] The target Artifact exists and is locatable;</li><li>[ ] The validator passes;</li><li>[ ] Key assertions have sources;</li><li>[ ] Changes have a diff or version;</li><li>[ ] There are no unauthorized side effects;</li><li>[ ] External actions have a Receipt;</li><li>[ ] Failures and incomplete items have been stated;</li><li>[ ] Token, time, and cost are recorded;</li><li>[ ] The workspace, credentials, and lease have been reclaimed;</li><li>[ ] The user can view, revoke, or continue.</li></ul><h2 id="final-definition-of-task-coverage" tabindex="-1">Final Definition of Task Coverage <a class="header-anchor" href="#final-definition-of-task-coverage" aria-label="Permalink to &quot;Final Definition of Task Coverage&quot;">​</a></h2><p>Hearth&#39;s goal is not to promise &quot;any software, any scenario, 100% unattended.&quot; Its goals are:</p><ul><li>To provide end-to-end coverage for eight categories of digital content work;</li><li>To gradually improve reliability and autonomy for each Task category;</li><li>To safely stop and hand to a human for Tasks that cannot be completed reliably;</li><li>To let users avoid understanding the internal architecture or repeatedly providing context;</li><li>To ensure every completion has evidence, permissions, and a Receipt.</li></ul><p>Coverage maturity should be expressed in layers:</p><table tabindex="0"><thead><tr><th>Level</th><th>Meaning</th></tr></thead><tbody><tr><td>Attemptable</td><td>The system can enter the Task family and produce a draft</td></tr><tr><td>Completable</td><td>It passes verification on representative Tasks</td></tr><tr><td>Reliable</td><td>It is stable across repeated real-world use, and failures are recoverable</td></tr><tr><td>Proactive</td><td>It requires no manual trigger within a Mandate</td></tr><tr><td>Unattended</td><td>It runs for extended periods with controllable risk</td></tr></tbody></table><p>Do not pass off &quot;Attemptable&quot; as &quot;Unattended&quot;.</p>',15)])])}const u=t(o,[["render",r]]);export{f as __pageData,u as default};
